$(function() {
    setTimeout(
        function(){
            $('.condition-block').hide();
        }, 100);


    $(document).on("change", "#voucher-ledger-grid .voucher", function (e) {
        actionVoucher($(this));
    });

    $(document).on("change", "#voucher-ledger-grid ._paymentby", function (e) {
        actionPaymentBy($(this));
    });
});

function actionVoucher(obj)
{
    var val = obj.val(),
        tr = obj.closest('tr');

    paymentByDisplay('hide',tr);
    partyDisplay('hide',tr);
    toPartyDisplay('hide',tr);
    accheadDisplay('hide',tr);
    bankDisplay('hide',tr);
    transactionDisplay('hide',tr);
    toBankDisplay('hide',tr);
    suspensionDisplay('hide',tr);
    amountDisplay('hide',tr);
    debitDisplay('hide',tr);
    creditDisplay('hide',tr);
    refDisplay('hide',tr);
    noteDisplay('hide',tr);


    if (val == '') {
        return;
    }
    refDisplay('show',tr);
    noteDisplay('show',tr);
    var paymentoption, paymentoptiontext;
    switch (val) {
        case'DEBIT':
        case'ASSET':
        case'CREDIT':
        case'LOAN':
            var accheadoption, accheadoptiontext;
            accheadDisplay('show',tr);
            partyDisplay('show',tr);
            paymentByDisplay('show',tr);
            amountDisplay('show',tr)
            switch (val) {
                case 'DEBIT':
                case 'CREDIT':
                    accheadoption = accheaddata.voucher;
                    break;
                case 'ASSET':
                    accheadoption = accheaddata.asset;
                    break;
                case 'LOAN':
                    accheadoption = accheaddata.loan;
                    break;
            }
            accheadoptiontext = '<option value="">SELECT</option>';
            for (i = 0; i < accheadoption.length; i++) {
                accheadoptiontext += '<option value="' + accheadoption[i].id + '">' + accheadoption[i].name + '</option>';
            }

            if (tr.find('.accheadid').html() != accheadoptiontext) {
                tr.find('.accheadid').html(accheadoptiontext).trigger('chosen:updated');
            }
            paymentoption = paymentdata.voucher;
            break;

        case'BANK':
            var bankoption, bankoptiontext;
            bankDisplay('show',tr);
            transactionDisplay('show',tr);
            debitDisplay('show',tr);
            creditDisplay('show',tr);
            bankoption = bankdata.all;
            bankoptiontext = '<option value="">SELECT</option>';
            for(i=0; i < bankoption.length; i++){
                bankoptiontext += '<option value="'+bankoption[i].id+'">'+bankoption[i].short_name+'</option>';
            }

            if(tr.find('.bankid').html() != bankoptiontext) {
                tr.find('.bankid').html(bankoptiontext).trigger('chosen:updated');
            }
            paymentoption = paymentdata.bank;
            break;
        case'BANKTOBANK':
            var bankoption, bankoptiontext;
            transactionDisplay('show',tr);
            toBankDisplay('show',tr);
            amountDisplay('show',tr);
            bankoption = bankdata.all;
            bankoptiontext = '<option value="">SELECT</option>';
            for(i=0; i < bankoption.length; i++){
                bankoptiontext += '<option value="'+bankoption[i].id+'">'+bankoption[i].short_name+'</option>';
            }

            if(tr.find('.bankid').html() != bankoptiontext) {
                tr.find('.bankid').html(bankoptiontext).trigger('chosen:updated');
            }
            paymentoption = paymentdata.bank;
            break;
        case'PARTY':
            partyDisplay('show',tr);
            paymentByDisplay('show',tr);
            debitDisplay('show',tr);
            creditDisplay('show',tr);
            paymentoption = paymentdata.party;
            break;
        case'PARTYTOPARTY':
            toPartyDisplay('show',tr);
            amountDisplay('show',tr);
            paymentoption = paymentdata.party;
            break;
        case'SUSPENSION':
            suspensionDisplay('show',tr);
            paymentByDisplay('show',tr);
            debitDisplay('show',tr);
            creditDisplay('show',tr);
            paymentoption = paymentdata.suspension;
            break;
    }

    paymentoptiontext = '<option value="">SELECT</option>';
    for(i=0; i < paymentoption.length; i++){
        paymentoptiontext += '<option value="'+paymentoption[i]+'">'+paymentoption[i]+'</option>';
    }

    if(tr.find('._').html() != paymentoptiontext) {
        tr.find('._paymentby').html(paymentoptiontext).trigger('chosen:updated');
    }

}

function actionPaymentBy(obj)
{
    var val = obj.val(),
        tr = obj.closest('tr'),
        vchr = tr.find('.voucher').val();
    toPartyDisplay('hide',tr);
    toBankDisplay('hide',tr);
    transactionDisplay('hide',tr);
    partyDisplay('show',tr,false);
    switch(val){
        case'DUE':
        case'PARTY':
            partyDisplay('show',tr);
            bankDisplay('hide',tr);
            transactionDisplay('hide',tr);
            if(vchr == 'SUSPENSION') {
                suspensionDisplay('show',tr);
            } else {
                suspensionDisplay('hide',tr);
            }
            break;
        case'CASH':
            suspensionDisplay('hide',tr);
            bankDisplay('hide',tr);
            transactionDisplay('hide',tr);
            break;
        case'SUSPENSION':
            suspensionDisplay('show',tr);
            bankDisplay('hide',tr);
            transactionDisplay('hide',tr);
            break;
        case'BANK':
        case'MOBILE BANK':
        case'CREDIT CARD':
            var option, optiontext;
            bankDisplay('show',tr);
            transactionDisplay('show',tr);
            suspensionDisplay('hide',tr);
            optiontext = '';
            switch(val){
                case 'BANK':
                    option = bankdata.bank;
                    optiontext = '<option value="">SELECT</option>';
                    break;
                case 'MOBILE BANK':
                    option = bankdata.mobilebank;
                    optiontext = '<option value="">SELECT</option>';
                    break;
                case 'CREDIT CARD':
                    option = bankdata.creditcard;
                    optiontext = '<option value="">SELECT</option>';
                    break;
            }

            for(i=0; i < option.length; i++){
                optiontext += '<option value="'+option[i].id+'">'+option[i].short_name+'</option>';
            }

            if(tr.find('.bankid').html() != optiontext) {
                tr.find('.bankid').html(optiontext).trigger('chosen:updated');
            }
            break;
    }
}



function refDisplay(flag,tr)
{
    if(flag == 'show'){
        tr.find('.ref-block').show();
    } else {
        tr.find('.ref-block').hide();
    }
}

function noteDisplay(flag,tr)
{
    if(flag == 'show'){
        tr.find('.note-block').show();
    } else {
        tr.find('.note-block').hide();
    }
}

function paymentByDisplay(flag,tr)
{
    if(flag == 'show'){
        tr.find('.payment-block').show();
        tr.find('._paymentby').prop('required',true);
    } else {
        tr.find('.payment-block').hide();
        tr.find('._paymentby').prop('required',false);
    }
}

function partyDisplay(flag,tr,required)
{
    required = (typeof required !== 'undefined') ?  required : true;
    if(flag == 'show'){
        tr.find('.party-block').show();
        if(required) {
            tr.find('.partyid').prop('required', true);
        } else {
            tr.find('.partyid').prop('required', false);
        }
    } else {
        tr.find('.party-block').hide();
        tr.find('.partyid').prop('required',false);
    }
}

function toPartyDisplay(flag,tr)
{
    if(flag == 'show'){
        tr.find('.fromparty-block').show();
        tr.find('.frompartyid').prop('required',true);
        tr.find('.toparty-block').show();
        tr.find('.topartyid').prop('required',true);
    } else {
        tr.find('.toparty-block').hide();
        tr.find('.topartyid').prop('required',false);
        tr.find('.toparty-block').hide();
        tr.find('.topartyid').prop('required',false);
    }
}


